def parse(block):
    out = []
    for line in block.strip().splitlines():
        parts = line.split("|")
        while len(parts) < 7:
            parts.append("")
        out.append(dict(num=parts[0], py=parts[1], cn=parts[2], loc=parts[3],
                        ind=parts[4], flags=parts[5], cat=parts[6]))
    return out


POINTS = {m[0]: parse(RAW[m[0]]) for m in MERIDIANS}
EXTRAS = parse(EXTRA)

if __name__ == "__main__":
    tot = 0
    for m in MERIDIANS:
        n = len(POINTS[m[0]])
        tot += n
        nums = [int(p["num"]) for p in POINTS[m[0]]]
        assert nums == list(range(1, n + 1)), m[0]
        print(m[0], n)
    print("TOTAL", tot, "extras", len(EXTRAS))
